-- Table: counseling_appointments
DROP TABLE IF EXISTS `counseling_appointments`;
CREATE TABLE `counseling_appointments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `appointment_date` date NOT NULL,
  `appointment_time` time NOT NULL,
  `concern_type` enum('academic','personal','behavioral','career','family','other') DEFAULT 'other',
  `urgency_level` enum('low','medium','high','urgent') DEFAULT 'medium',
  `concern_description` text NOT NULL,
  `status` enum('pending','confirmed','in_progress','completed','cancelled','rescheduled','missed','follow_up_scheduled') DEFAULT 'pending',
  `assigned_advocate_id` int(11) DEFAULT NULL COMMENT 'Guidance counselor/advocate assigned to handle the session',
  `confirmed_at` timestamp NULL DEFAULT current_timestamp() COMMENT 'Auto-set when appointment is created',
  `original_appointment_id` int(11) DEFAULT NULL,
  `parent_appointment_id` int(11) DEFAULT NULL COMMENT 'Links follow-up to original appointment',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `nature_of_contact` enum('walk-in','voluntary','referral_interview','consultation','follow-up','guidance_personnel_initiated','online') DEFAULT 'walk-in',
  `booking_type` enum('regular','follow_up','walk_in') DEFAULT 'regular' COMMENT 'Type of booking',
  `date_of_contact` date DEFAULT NULL,
  `session_summary` text DEFAULT NULL,
  `follow_up_needed` tinyint(1) DEFAULT 0,
  `follow_up_date` date DEFAULT NULL,
  `is_follow_up` tinyint(1) DEFAULT 0 COMMENT 'Flag to identify follow-up appointments',
  `session_duration` int(11) DEFAULT 60 COMMENT 'Duration in minutes',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `original_appointment_id` (`original_appointment_id`),
  KEY `idx_assigned_advocate` (`assigned_advocate_id`),
  KEY `idx_parent_appointment` (`parent_appointment_id`),
  CONSTRAINT `counseling_appointments_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `counseling_appointments_ibfk_3` FOREIGN KEY (`original_appointment_id`) REFERENCES `counseling_appointments` (`id`),
  CONSTRAINT `counseling_appointments_ibfk_4` FOREIGN KEY (`assigned_advocate_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

