-- Table: counseling_forms
DROP TABLE IF EXISTS `counseling_forms`;
CREATE TABLE `counseling_forms` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `appointment_id` int(11) NOT NULL COMMENT 'Reference to counseling_appointments table',
  `student_id` int(11) NOT NULL COMMENT 'Reference to users table (student)',
  `counselor_id` int(11) NOT NULL COMMENT 'Reference to users table (counselor)',
  `student_name` varchar(255) NOT NULL COMMENT 'Student full name (auto-filled)',
  `session_date` date NOT NULL COMMENT 'Date of the counseling session (auto-filled)',
  `problem` text NOT NULL COMMENT 'Student problem or concern',
  `counselor_observation` text NOT NULL COMMENT 'What the counselor observes about the student',
  `student_reaction` text NOT NULL COMMENT 'How the student reacts during the session',
  `discussion_topics` text NOT NULL COMMENT 'What was discussed during the session',
  `advice_given` text NOT NULL COMMENT 'Advice or recommendations given to the student',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `appointment_id` (`appointment_id`),
  KEY `student_id` (`student_id`),
  KEY `counselor_id` (`counselor_id`),
  KEY `session_date` (`session_date`),
  KEY `idx_counseling_forms_lookup` (`student_id`,`session_date`),
  KEY `idx_counseling_forms_counselor` (`counselor_id`,`session_date`),
  CONSTRAINT `counseling_forms_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `counseling_appointments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `counseling_forms_ibfk_2` FOREIGN KEY (`student_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `counseling_forms_ibfk_3` FOREIGN KEY (`counselor_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Counseling session records with updated form structure';

-- Table: counseling_remarks
DROP TABLE IF EXISTS `counseling_remarks`;
CREATE TABLE `counseling_remarks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `appointment_id` int(11) NOT NULL,
  `counselor_id` int(11) NOT NULL,
  `session_date` date NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `remarks` text DEFAULT NULL COMMENT 'Optional counselor remarks/notes',
  PRIMARY KEY (`id`),
  KEY `appointment_id` (`appointment_id`),
  KEY `counselor_id` (`counselor_id`),
  CONSTRAINT `counseling_remarks_ibfk_1` FOREIGN KEY (`appointment_id`) REFERENCES `counseling_appointments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `counseling_remarks_ibfk_2` FOREIGN KEY (`counselor_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table: daily_booking_limits
DROP TABLE IF EXISTS `daily_booking_limits`;
CREATE TABLE `daily_booking_limits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `max_appointments` int(11) NOT NULL DEFAULT 8,
  `set_by` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `date` (`date`),
  KEY `set_by` (`set_by`),
  KEY `idx_date` (`date`),
  CONSTRAINT `daily_booking_limits_ibfk_1` FOREIGN KEY (`set_by`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=105 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: entrance_exam_appointments
DROP TABLE IF EXISTS `entrance_exam_appointments`;
CREATE TABLE `entrance_exam_appointments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `preferred_date` date NOT NULL,
  `preferred_time` time NOT NULL,
  `grade_level_applying` varchar(50) NOT NULL,
  `previous_school` varchar(100) DEFAULT NULL,
  `status` enum('pending','confirmed','awaiting_results','completed','cancelled','missed') DEFAULT 'pending' COMMENT 'pending=booked, confirmed=approved by staff, awaiting_results=exam taken but results not released, completed=results released, cancelled=appointment cancelled, missed=student did not show up',
  `confirmed_by` int(11) DEFAULT NULL,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `exam_score` decimal(5,2) DEFAULT NULL,
  `exam_result` enum('passed','failed','pending') DEFAULT 'pending',
  `exam_date` date DEFAULT NULL,
  `olsat_level` varchar(50) DEFAULT NULL,
  `olsat_form` varchar(50) DEFAULT NULL,
  `verbal_abilities_score` int(11) DEFAULT NULL,
  `verbal_comprehension_score` int(11) DEFAULT NULL,
  `verbal_reasoning_score` int(11) DEFAULT NULL,
  `nonverbal_abilities_score` int(11) DEFAULT NULL,
  `figural_reasoning_score` int(11) DEFAULT NULL,
  `quantitative_reasoning_score` int(11) DEFAULT NULL,
  `total_score` int(11) DEFAULT NULL,
  `total_items` int(11) DEFAULT 72,
  `stanine_score` int(11) DEFAULT NULL,
  `verbal_stanine` int(11) DEFAULT NULL,
  `verbal_interpretation` text DEFAULT NULL,
  `nonverbal_stanine` int(11) DEFAULT NULL,
  `nonverbal_interpretation` text DEFAULT NULL,
  `interpretation` text DEFAULT NULL,
  `qualified_grade` varchar(20) DEFAULT NULL,
  `academic_strand` varchar(100) DEFAULT NULL,
  `preferred_program` varchar(100) DEFAULT NULL COMMENT 'Program preferred by examinee (for college/higher ed students)',
  `qualified_program` varchar(100) DEFAULT NULL COMMENT 'Program qualified for based on exam results (determined by admin/guidance)',
  `school_year` varchar(20) DEFAULT NULL,
  `testing_in_charge` varchar(100) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `assisted_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `confirmed_by` (`confirmed_by`),
  KEY `assisted_by` (`assisted_by`),
  KEY `idx_exam_result` (`exam_result`),
  KEY `idx_preferred_program` (`preferred_program`),
  KEY `idx_qualified_program` (`qualified_program`),
  CONSTRAINT `entrance_exam_appointments_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `entrance_exam_appointments_ibfk_2` FOREIGN KEY (`confirmed_by`) REFERENCES `users` (`id`),
  CONSTRAINT `entrance_exam_appointments_ibfk_3` FOREIGN KEY (`assisted_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: entrance_exam_daily_limits
DROP TABLE IF EXISTS `entrance_exam_daily_limits`;
CREATE TABLE `entrance_exam_daily_limits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `max_appointments` int(11) NOT NULL DEFAULT 5,
  `exam_time` time DEFAULT '09:00:00',
  `exam_end_time` time DEFAULT NULL,
  `set_by` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `date` (`date`),
  KEY `set_by` (`set_by`),
  KEY `idx_date` (`date`),
  CONSTRAINT `entrance_exam_daily_limits_ibfk_1` FOREIGN KEY (`set_by`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


-- Table: holidays
